'use strict';
$('addImage').onclick=()=>$('imageLayerFile').click();
$('imageLayerFile').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;if(layers.length+files.length>150){toast('В проекте может быть не больше 150 объектов.');e.target.value='';return}const originalBase=base,prepared=[];let skipped=0;const button=$('addImage');button.disabled=true;try{for(const file of files){if(file.size>30e6){skipped++;continue}const url=URL.createObjectURL(file);try{const image=await loadImg(url),ratio=Math.min(1,2400/Math.max(image.width,image.height)),bitmap=off(Math.max(1,Math.round(image.width*ratio)),Math.max(1,Math.round(image.height*ratio)));bitmap.getContext('2d').drawImage(image,0,0,bitmap.width,bitmap.height);prepared.push({name:file.name,img:bitmap})}catch{skipped++}finally{URL.revokeObjectURL(url)}}if(base!==originalBase){toast('Исходное фото изменилось. Добавьте картинки ещё раз.');return}if(!prepared.length){toast('Не удалось открыть картинки. Поддерживаются PNG, JPEG и WebP до 30 МБ.');return}if(layers.length+prepared.length>150){toast('Превышен лимит 150 объектов.');return}checkpoint();for(const [index,item] of prepared.entries()){const offset=(index%5)*20,layer={...item,id:++seq,x:base.width/2+offset,y:base.height/2+offset,scale:Math.min(1,base.width*.7/item.img.width,base.height*.7/item.img.height),angle:0,opacity:1,visible:true,tint:null};layers.push(layer);active=layer.id}selected=new Set([active]);selection=null;setMode('move');ui();toast('Добавлено картинок: '+prepared.length+(skipped?'. Пропущено файлов: '+skipped:'. Двигайте и оформляйте их как обычные объекты.'))}finally{button.disabled=false;e.target.value=''}};
